package controller;

import constants.Message;
import dto.AccountDTO;
import dto.ResponseDTO;
import repository.AccountRepository;
import view.AccountView;

/**
 * Nhan phieu dang nhap tu Main (da qua captcha), hoi Repository, dua ket qua cho View in 1 lan.
 * Bai khong co tinh toan nghiep vu nen KHONG co tang service.
 *
 * @author CuongThai Academy
 */
public class AccountController {

    // Kho tai khoan (Controller goi thang Repository vi bai khong co service)
    private AccountRepository accountRepository;

    // Man hinh in ket qua
    private AccountView accountView;

    // Constructor: tao kho (nap san tai khoan mau) va man hinh
    public AccountController() {
        accountRepository = new AccountRepository();
        accountView = new AccountView();
    }

    // Dang nhap bang phieu Main da kiem (ca captcha), in ket qua 1 lan
    public void login(AccountDTO accountDTO) {
        ResponseDTO responseDTO = new ResponseDTO();

        // Dung tai khoan va mat khau thi bao thanh cong, nguoc lai bao that bai
        if (accountRepository.checkLogin(accountDTO)) {
            responseDTO.setMessage(Message.getLoginSuccess());
        } else {
            // Sai so tai khoan hoac mat khau
            responseDTO.setMessage(Message.getLoginFailed());
        }

        accountView.setResponseDTO(responseDTO);
        accountView.display();
    }
}

