/**
 * Kho giu danh sach tai khoan ngan hang, kiem tai khoan + mat khau co dung khong.
 *
 * @author CuongThai Academy
 */
public class AccountRepository {

    // Danh sach tai khoan co san
    private List<Account> accountList;

    // Tao kho va nap cac tai khoan mau
    public AccountRepository() {
        this.accountList = new ArrayList<>();

        // Moi vong them 1 tai khoan mau (so tai khoan + mat khau cung vi tri)
        for (int i = 0; i < Constants.SAMPLE_ACCOUNT_ARRAY.length; i++) {
            accountList.add(new Account(Constants.SAMPLE_ACCOUNT_ARRAY[i],
                    Constants.SAMPLE_PASSWORD_ARRAY[i]));
        }
    }

    // Kiem dang nhap: true neu co tai khoan trung ca so tai khoan lan mat khau
    public boolean checkLogin(AccountDTO accountDTO) {
        // Duyet tung tai khoan trong kho
        for (Account account : accountList) {
            // Trung ca 2 thi dang nhap dung
            if ((accountDTO.getAccount().equals(account.getAccount())) &&
                    (accountDTO.getPassword().equals(account.getPassword()))) {
                return true;
            }
        }

        return false;
    }
}

